function draw(ctx, t, p) {
  const W = 960, H = 540;
  const TAU = Math.PI * 2;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const lerp = (a, b, u) => a + (b - a) * u;
  const num = (v, d) => Number.isFinite(Number(v)) ? Number(v) : d;
  const fmt = (v, n) => (Number.isFinite(v) ? v.toFixed(n == null ? 2 : n) : "—");
  const x0raw = clamp(num(p.x0, 1), -2, 2);
  const mag = clamp(num(p.h, 0.5), 0.02, 2);
  const side = num(p.side, 1) < 0 ? -1 : 1;
  const example = num(p.example, 0) >= 0.5 ? 1 : 0;
  const sceneEnds = [8, 22, 36, 50, 64, 78];
  const sec = clamp(t, 0, 1) * 78;
  let si = 0;
  while (si < 5 && sec >= sceneEnds[si]) si++;
  const start = si === 0 ? 0 : sceneEnds[si - 1];
  const local = clamp((sec - start) / (sceneEnds[si] - start), 0, 1);
  const isAbs = si === 5 || example === 1;
  const x0 = isAbs ? 0 : x0raw;
  let h = side * mag;
  if (si === 2) h = side * lerp(1, 0.02, local);
  if (si === 3) h = side * mag;
  if (si === 5) h = side * mag;
  const f = x => isAbs ? Math.abs(x) : x * x;
  const deriv = isAbs ? (x0 < 0 ? -1 : x0 > 0 ? 1 : NaN) : 2 * x0;
  const qx = x0 + h;
  const fp = f(x0), fq = f(qx);
  const slope = h !== 0 ? (fq - fp) / h : deriv;
  const tangent = Number.isFinite(deriv) ? (x => fp + deriv * (x - x0)) : null;
  const residual = isAbs ? NaN : fq - (fp + deriv * h);

  ctx.fillStyle = "#f7fafc";
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = "#18324a";
  ctx.font = "bold 23px sans-serif";
  ctx.fillText("割线旋转成切线：导数的极限定义", 35, 42);
  ctx.font = "17px sans-serif";
  ctx.fillStyle = "#536b7d";
  ctx.fillText("时间轴按 78 秒累计推进镜头；h 始终非零", 650, 42);

  const gx0 = 55, gx1 = 650, gy0 = 100, gy1 = 405;
  const xmin = -3, xmax = 3, ymin = -1, ymax = 9;
  const X = x => gx0 + (x - xmin) / (xmax - xmin) * (gx1 - gx0);
  const Y = y => gy1 - (y - ymin) / (ymax - ymin) * (gy1 - gy0);
  const safeY = y => clamp(y, ymin, ymax);

  ctx.fillStyle = "#ffffff";
  ctx.fillRect(gx0, gy0, gx1 - gx0, gy1 - gy0);
  ctx.strokeStyle = "#dbe7ef";
  ctx.lineWidth = 1;
  for (let x = -3; x <= 3; x++) { ctx.beginPath(); ctx.moveTo(X(x), gy0); ctx.lineTo(X(x), gy1); ctx.stroke(); }
  for (let y = 0; y <= 9; y++) { ctx.beginPath(); ctx.moveTo(gx0, Y(y)); ctx.lineTo(gx1, Y(y)); ctx.stroke(); }
  ctx.strokeStyle = "#35566d";
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(gx0, Y(0)); ctx.lineTo(gx1, Y(0)); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(X(0), gy1); ctx.lineTo(X(0), gy0); ctx.stroke();
  ctx.fillStyle = "#35566d";
  ctx.font = "16px sans-serif";
  for (let x = -3; x <= 3; x++) ctx.fillText(String(x), X(x) - 5, Y(0) + 22);
  for (let y = 0; y <= 9; y += 2) ctx.fillText(String(y), X(0) + 8, Y(y) + 5);
  ctx.fillText("x", gx1 - 12, Y(0) - 8);
  ctx.fillText("y", X(0) + 10, gy0 + 14);

  function curve(fn, color, width, dash) {
    ctx.save(); ctx.strokeStyle = color; ctx.lineWidth = width || 3;
    ctx.setLineDash(dash || []); ctx.beginPath();
    let first = true;
    for (let i = 0; i <= 180; i++) {
      const x = xmin + (xmax - xmin) * i / 180, y = fn(x);
      const px = X(x), py = Y(safeY(y));
      if (first) { ctx.moveTo(px, py); first = false; } else ctx.lineTo(px, py);
    }
    ctx.stroke(); ctx.restore();
  }
  curve(f, "#236fb5", 3);
  if (!isAbs && tangent && si >= 2) curve(tangent, "#9b55b6", 2, [8, 6]);

  function point(x, y, color, r) {
    ctx.fillStyle = color; ctx.beginPath(); ctx.arc(X(x), Y(safeY(y)), r || 6, 0, TAU); ctx.fill();
  }
  function lineWorld(xa, ya, xb, yb, color, width, dash) {
    ctx.save(); ctx.strokeStyle = color; ctx.lineWidth = width || 2; ctx.setLineDash(dash || []);
    ctx.beginPath(); ctx.moveTo(X(xa), Y(safeY(ya))); ctx.lineTo(X(xb), Y(safeY(yb))); ctx.stroke(); ctx.restore();
  }

  const showQ = si !== 0 || local > 0.15;
  point(x0, fp, "#f28e2b", 7);
  if (showQ) {
    point(qx, fq, "#7a4aa8", 6);
    lineWorld(x0, fp, qx, fq, "#7a4aa8", 3);
    lineWorld(x0, fp, qx, fp, "#e58b32", 2, [5, 5]);
    lineWorld(qx, fp, qx, fq, "#e58b32", 2, [5, 5]);
  }
  if (si >= 4 && !isAbs) {
    lineWorld(qx, fq, qx, fp + deriv * h, "#d84b4b", 4);
    point(qx, fp + deriv * h, "#d84b4b", 4);
  }

  ctx.fillStyle = "#18324a";
  ctx.font = "bold 19px sans-serif";
  ctx.fillText(isAbs ? "示例：f(x)=|x|" : "主例：f(x)=x²", 70, 125);
  ctx.font = "17px sans-serif";
  ctx.fillStyle = "#334e60";
  ctx.fillText("P", X(x0) + 9, Y(fp) - 10);
  if (showQ) ctx.fillText("Q", X(qx) + 9, Y(fq) - 8);
  ctx.fillStyle = "#e58b32";
  ctx.fillText("Δx = h = " + fmt(h, 3), 410, 385);
  if (showQ) ctx.fillText("Δy = " + fmt(fq - fp, 3), 415, 365);

  const bx = 680, by = 92, bw = 245;
  ctx.fillStyle = "#edf4f8"; ctx.fillRect(bx, by, bw, 315);
  ctx.strokeStyle = "#c6d9e5"; ctx.strokeRect(bx, by, bw, 315);
  ctx.fillStyle = "#18324a"; ctx.font = "bold 18px sans-serif";
  const titles = ["固定点与附近的动点", "用增量构造割线斜率", "从右侧逼近切线", "左右极限必须一致", "切线为何能近似曲线", "连续的尖点为何不可导"];
  ctx.fillText("S" + (si + 1) + "  " + titles[si], bx + 14, by + 28);
  ctx.font = "17px sans-serif"; ctx.fillStyle = "#334e60";
  const rows = isAbs ? [
    "x₀ = 0（尖点固定）", "|h| = " + fmt(Math.abs(h), 3), "m(h) = |h| / h = " + fmt(slope, 2),
    "左侧斜率 = -1", "右侧斜率 = 1", "连续，但不可导"
  ] : [
    "x₀ = " + fmt(x0, 2), "|h| = " + fmt(Math.abs(h), 3), "m(h) = 2x₀ + h = " + fmt(slope, 3),
    "f′(x₀) = 2x₀ = " + fmt(deriv, 2), "h² 误差 = " + fmt(Math.abs(residual), 5),
    "误差比 = " + fmt(Math.abs(residual) / Math.abs(h), 5)
  ];
  for (let i = 0; i < rows.length; i++) ctx.fillText(rows[i], bx + 16, by + 66 + i *  thirty(), bw - 28);
  function thirty() { return 34; }

  ctx.fillStyle = "#18324a"; ctx.font = "bold 18px sans-serif";
  ctx.fillText("关键关系", 680, 430);
  ctx.font = "17px sans-serif"; ctx.fillStyle = "#334e60";
  let formula = isAbs ? "m(h)=|h|/h；左右极限不相等" : (si >= 4 ? "L(x)=x₀²+2x₀(x−x₀)，误差=h²" : "m(h)=[f(x₀+h)−f(x₀)]/h=2x₀+h");
  ctx.fillText(formula, 780, 430);
  ctx.fillStyle = "#236fb5"; ctx.fillText("蓝：曲线", 55, 425);
  ctx.fillStyle = "#f28e2b"; ctx.fillText("橙：P、增量", 160, 425);
  ctx.fillStyle = "#7a4aa8"; ctx.fillText("紫：割线/切线", 300, 425);

  return { metrics: {
    scene: si + 1,
    elapsedSeconds: sec,
    x0: x0,
    h: h,
    slope: Number.isFinite(slope) ? slope : "不存在",
    derivative: Number.isFinite(deriv) ? deriv : "不存在",
    residual: Number.isFinite(residual) ? residual : "不适用"
  }};
}
